@Component("trainingCourse-handler")
@ProcessingGroup("trainingCourse-processing-group")
public class TrainingCourseEventHandler {
	
	// core constructor
	TrainingCourseEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateTrainingCourseEvent
     */
    @EventHandler
    public void handle( CreateTrainingCourseEvent event) {
        entityManager.persist(new TrainingCourse(event.getTrainingCourseId(), event.getCode(), event.getTitle(), event.getDurationHours(), event.getPrerequisites(), event.getEnrollments(), event.getJobProfiles(), event.getDeliveryMethod()));
    }

    /*
     * @param	event UpdateTrainingCourseEvent
     */
    @EventHandler
    public TrainingCourse handle( UpdateTrainingCourseEvent event) {
    	entityManager.merge(new TrainingCourse(event.getTrainingCourseId(), event.getCode(), event.getTitle(), event.getDurationHours(), event.getPrerequisites(), event.getEnrollments(), event.getJobProfiles(), event.getDeliveryMethod()));
    }
    
    /*
     * @param	event DeleteTrainingCourseEvent
     */
    @EventHandler
    public void on( DeleteTrainingCourseEvent event) {
    	TrainingCourse entity = new TrainingCourse();
   
    	// ------------------------------------------
    	// apply the TrainingCourseId
    	// ------------------------------------------
    	entity.setTrainingCourseId( event.getTrainingCourseId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final TrainingCourseRepository trainingCourseEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(TrainingCourseEventHandler.class.getName());

}
